import { fetchServices, type Service } from "./api/client";
import { statusCard } from "./components/statusCard";
import { formatAgo } from "./utils/format";

const REFRESH_MS = Number(import.meta.env.VITE_REFRESH_SECONDS ?? 15) * 1000;

async function render(root: HTMLElement): Promise<void> {
  const services: Service[] = await fetchServices();
  const down = services.filter((s) => s.status !== "up").length;

  root.replaceChildren(
    header(services.length, down),
    ...services.map(statusCard),
  );
}

function header(total: number, down: number): HTMLElement {
  const el = document.createElement("header");
  el.className = "board__header";
  el.textContent = down === 0
    ? `All ${total} services are healthy`
    : `${down} of ${total} services need attention`;
  el.dataset.updated = formatAgo(new Date());
  return el;
}

const root = document.querySelector<HTMLElement>("#app");
if (root) {
  void render(root);
  setInterval(() => void render(root), REFRESH_MS);
}

