import { z } from "zod";

const API_URL = import.meta.env.VITE_API_URL ?? "http://localhost:8080";

export const ServiceSchema = z.object({
  id: z.string(),
  name: z.string(),
  status: z.enum(["up", "degraded", "down"]),
  latencyMs: z.number().nonnegative(),
  checkedAt: z.coerce.date(),
});

export type Service = z.infer<typeof ServiceSchema>;

export class ApiError extends Error {
  constructor(public readonly status: number, message: string) {
    super(message);
  }
}

export async function fetchServices(signal?: AbortSignal): Promise<Service[]> {
  const res = await fetch(`${API_URL}/api/services`, { signal });
  if (!res.ok) throw new ApiError(res.status, `GET /api/services failed: ${res.status}`);
  return z.array(ServiceSchema).parse(await res.json());
}

