import type { Service } from "../api/client";
import { formatAgo, formatLatency } from "../utils/format";

const LABEL: Record<Service["status"], string> = {
  up: "Healthy",
  degraded: "Degraded",
  down: "Down",
};

export function statusCard(service: Service): HTMLElement {
  const card = document.createElement("article");
  card.className = `card card--${service.status}`;
  card.innerHTML = `
    <span class="card__dot" aria-hidden="true"></span>
    <h2 class="card__name">${service.name}</h2>
    <p class="card__meta">${LABEL[service.status]} · ${formatLatency(service.latencyMs)}</p>
    <time class="card__time">${formatAgo(service.checkedAt)}</time>
  `;
  return card;
}

