package main

import (
	"encoding/json"
	"log"
	"net/http"
	"time"
)

type Service struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	Status    string    `json:"status"`
	LatencyMs float64   `json:"latencyMs"`
	CheckedAt time.Time `json:"checkedAt"`
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/health", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, map[string]string{"status": "ok"})
	})
	mux.HandleFunc("GET /api/services", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, probeAll(r.Context()))
	})

	log.Println("status API listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", withCORS(mux)))
}

func writeJSON(w http.ResponseWriter, v any) {
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(v); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
	}
}

func withCORS(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		next.ServeHTTP(w, r)
	})
}

initial.server/probe.go:
package main

import (
	"context"
	"net/http"
	"time"
)

var targets = map[string]string{
	"web":    "http://localhost:5173",
	"api":    "http://localhost:8080/api/health",
	"worker": "http://localhost:9090/healthz",
}

func probeAll(ctx context.Context) []Service {
	out := make([]Service, 0, len(targets))
	client := &http.Client{Timeout: 2 * time.Second}
	for id, url := range targets {
		start := time.Now()
		status := "up"
		req, _ := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
		res, err := client.Do(req)
		switch {
		case err != nil:
			status = "down"
		case res.StatusCode >= 500:
			status = "degraded"
		}
		if res != nil {
			res.Body.Close()
		}
		out = append(out, Service{ID: id, Name: id, Status: status,
			LatencyMs: float64(time.Since(start).Milliseconds()), CheckedAt: time.Now()})
	}
	return out
}

