export interface RetryOptions {
  attempts?: number;
  delayMs?: number;
}

/** Runs fn until it succeeds, waiting a little longer after each failure. */
export async function withRetry<T>(fn: () => Promise<T>, { attempts = 3, delayMs = 250 }: RetryOptions = {}): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      await new Promise((r) => setTimeout(r, delayMs * 2 ** i));
    }
  }
  throw lastError;
}
